// (`docs/durability.md` §3.7, grammar §13.3, §14.5, PRD resolved q35, q50).
//
// # One ledger, two kinds
//
// A **delivery** is something the lifecycle owes a listener: it is journaled
// before it is attempted, it carries an ordinal a receiver orders by, and a
// process that dies mid-attempt leaves a row a later start finishes. There are
// two kinds of them and they differ in *who asked* rather than in how they are
// worked:
//
//  * `callback` — the lifecycle webhooks a request subscribed to with an `http`
//    trigger's `callback:` (grammar §13.3). The URL comes out of the request
//    payload, so it is attacker-controlled and is held to that trigger's
//    `callback_allow:` at the delivery. That half stays in `./serve.ts`, where
//    the trigger is.
//  * `trace_sink` — the settled trace every execution ships to the address the
//    deploy layer names (grammar §14.5, PRD resolved q50), and — the sink's
//    second event class — the envelope every settled detached `flow.*`
//    delivery ships of its own (PRD resolved q64). The URL is written by
//    the operator in the deploy file, beside the database credentials, and is
//    trusted on the terms a connection string is: there is no allowlist, and
//    `refused` — the status an allowlist miss produces — cannot apply to one.
//    That half is here.
//
// What both share is this module: the bounded schedule, the claim that keeps one
// row from being worked twice, the journal writes that record what each attempt
// did, and the one `fetch` this app makes on the lifecycle's behalf.
//
// # Never the execution's failure
//
// PRD resolved q50 states the invariant a reader should hold this file to: a
// sink outage costs deliveries a retry, never an execution. Nothing here is
// awaited by a graph, nothing here can throw into one, and every failure ends as
// a row with an outcome and a sentence on stderr. The trace is shipped from the
// hook that closes the lifecycle row, so an export is at-least-once with the rest
// of the ledger — and a run whose sink is a black hole still prints its answer
// and exits with the code its outcome earned. A detached delivery's envelope is
// shipped from the moment that delivery settles, which is past the join and
// downstream of everything the flow instance waits for (grammar 8.6 rule 7).

import { createHmac } from "node:crypto";
import process from "node:process";

import { ARTIFACT_HASH, COMPILER_VERSION } from "./artifact.ts";
import { deployTarget, traceSink } from "./deployment.ts";
import type { OutboundAuth } from "./deployment.ts";
import { exportRequest, parseTraceparent } from "./otlp.ts";
import {
  TRACE_VERSION,
  deliveriesOf,
  detachedTraceDocument,
  exhaustRecordedDelivery,
  intendDelivery,
  journaledExecution,
  recordDeliveryAttempt,
  traceSinkClass,
} from "./runtime.ts";
import type * as runtime from "./runtime.ts";

// ---------------------------------------------------------------------------
// The trace sink
// ---------------------------------------------------------------------------

/** Whether this target names an address every settled trace ships to. */
export function sinkConfigured(): boolean {
  return traceSink !== undefined;
}

/** The identity a sink delivery carries, or `undefined` for an open collector. */
export function sinkAuth(): OutboundAuth | undefined {
  return traceSink?.auth;
}

/**
 * The variables `trace_sink.auth:` names that resolved to **nothing**.
 *
 * The deploy layer's half of `./serve.ts`'s `blankCredentials`, and it lives
 * here because `traceSink` does — a second reader of the sink's shape would be a
 * second place to forget one of its two halves. Grammar §14.5 rule 3 makes the
 * sink's `auth:` §13.3's block "unchanged", and §13.3 says what an empty one is:
 * not a missing setting but an open door, refused at launch naming the variable.
 * A collector reached with `Authorization: Bearer ` and nothing after it, or with
 * a signature computed over a key of no bytes, is a deployment that believes it
 * is authenticating and is not.
 *
 * Both halves are asked about rather than one: a sink may declare `bearer:` and
 * `hmac:` together, and an empty key beside a good token is still a signature
 * anybody can forge.
 */
export function blankSinkCredentials(): readonly string[] {
  const auth = traceSink?.auth;
  const blank: string[] = [];
  if (auth?.bearer !== undefined && secret(auth.bearer.tokenEnv) === "") {
    blank.push(auth.bearer.tokenEnv);
  }
  if (auth?.hmac !== undefined && secret(auth.hmac.secretEnv) === "") {
    blank.push(auth.hmac.secretEnv);
  }
  return blank;
}

/** What a settled execution hands the exporter besides its entries. */
export interface SettledTrace {
  readonly execution: string;
  readonly flow: string;
  readonly status: "completed" | "failed" | "interrupted";
  readonly error?: string;
  readonly entries: readonly runtime.TraceEntry[];
}

/**
 * Journal this settled execution's trace delivery, and answer with the row.
 *
 * `undefined` for a target that declares no sink, and for an execution that
 * already has one — the settle is once per execution, and the ledger is what
 * says so across processes exactly as it does for a `settled` webhook: a
 * generation that journaled the row and died before the lifecycle row closed
 * leaves an execution that is still open *and* already exported, and a second
 * intent would ship one execution's trace under two delivery ids.
 *
 * **The body is serialized here**, at the intent, because that is what every
 * attempt resends: a signature is over what is sent, so a body re-serialized on
 * a later attempt — or in a later process — would be a second delivery wearing
 * the first one's id. It is also why the OTLP mapping happens now rather than
 * per attempt: the export has to be the same bytes each time or the trace ids a
 * receiver deduped on would move under it.
 *
 * Called from the hook that closes the lifecycle row and awaited there, so a
 * process killed a millisecond later leaves a `pending` row the next `serve`
 * start finishes.
 *
 * **It raises rather than answering** where the journal would not take the
 * intent, and that is what makes the caller's ladder mean something: the row
 * closes as this returns, so a write refused once — a second process holding the
 * file past the lock wait, a disk momentarily full, both states
 * `docs/durability.md` §2 says a healthy deployment reaches — is a trace nothing
 * will ever ship. Both callers wrap it in [`insisting`] and say what happened on
 * stderr when the ladder ends, which is §3.7's posture for a delivery: a
 * courtesy the trace file backstops, never the run's outcome.
 */
export async function shipTrace(
  settled: SettledTrace,
): Promise<runtime.DeliveryRecord | undefined> {
  const sink = traceSink;
  if (sink === undefined) return undefined;
  if (await exportedAlready(settled.execution)) return undefined;
  const document: runtime.TraceDocument = {
    trace_version: TRACE_VERSION,
    flow: settled.flow,
    execution_id: settled.execution,
    status: settled.status,
    ...(settled.error === undefined ? {} : { error: settled.error }),
    entries: settled.entries,
  };
  // The lifecycle row is what the export's clock window and its caller's trace
  // come off. It is read here rather than passed in because the process that
  // settles an execution need not be the one that started it: a recovered
  // execution's `traceparent` reached a `serve` that has since died
  // (`docs/durability.md` §6.1), and the row is where it survived.
  const row = await journaledExecution(settled.execution);
  const startedAt = row?.startedAt ?? new Date().toISOString();
  return await intendExport(sink, document, {
    startedAt,
    endedAt: new Date().toISOString(),
    traceparent: row?.traceparent,
  });
}

/**
 * Journal a settled **detached `flow.*` delivery**'s own envelope, and answer
 * with the row (PRD resolved q64, `docs/trace.md` §1.4).
 *
 * The sink's second event class, and the same channel as the first: one row on
 * the delivery ledger of the execution the delivery ran under, `kind:
 * "trace_sink"` and `event: "settled"` — a delivery that has stopped is what a
 * `settled` row records — worked on the same schedule, signed with the same
 * identity and shaped by the same `format:` switch. What tells the two classes
 * apart is the body's head (`detached: true`, or the root span's
 * `agentcompose.detached` under `format: otlp`), which is where a receiver
 * reads it too; the wire's `X-AgentCompose-Event` vocabulary is grammar 13.3's
 * and does not move.
 *
 * **No "already shipped" guard**, and the absence is the ruling rather than an
 * oversight. The parent's export is once per execution because a settle is; a
 * detached delivery is re-run by the recovery of its parent (`docs/durability.md`
 * §3.2) and re-ships on *that* settlement, so its envelope is at-least-once, and
 * a receiver dedupes on `(parent_execution, idempotency_key)` — grammar 9.4's
 * receiver-side rule, read one more time. A second row is a second delivery id
 * for the same delivery, which is exactly what that pair exists to fold.
 *
 * The window is the delivery's own — issued to settled — and the caller's trace,
 * where the parent's request carried one, is the parent's: the envelope is
 * exported **into** the trace its parent's export lands in (`docs/trace.md`
 * §12.2).
 */
export async function shipDetachedTrace(
  settled: runtime.DetachedSettlement,
): Promise<runtime.DeliveryRecord | undefined> {
  const sink = traceSink;
  if (sink === undefined) return undefined;
  const row = await journaledExecution(settled.parentExecution);
  return await intendExport(sink, detachedTraceDocument(settled), {
    startedAt: settled.dispatchedAt,
    endedAt: settled.settledAt,
    traceparent: row?.traceparent,
  });
}

/**
 * [`shipDetachedTrace`], insisted on, and said on stderr where the ladder ends.
 *
 * What both processes that settle executions call from their
 * `watchDetachedSettlements` listener: the intent is the one write nothing else
 * comes back to — no lifecycle row is closing for a delivery, and a replay
 * re-ships only where the parent is recovered — so a journal busy for a moment
 * costs the envelope a retry rather than the envelope. Never throws: the
 * listener it runs in is downstream of a delivery that has already settled, and
 * nothing it does may reach back (grammar 8.6 rule 7).
 */
export async function journalDetachedTrace(
  settled: runtime.DetachedSettlement,
): Promise<runtime.DeliveryRecord | undefined> {
  let journaled: runtime.DeliveryRecord | undefined;
  await insisting(async () => {
    try {
      journaled = await shipDetachedTrace(settled);
      return true;
    } catch (error) {
      process.stderr.write(
        `the detached delivery \`${settled.idempotencyKey}\`'s trace could not be journaled: ${message(error)}\n`,
      );
      return false;
    }
  });
  return journaled;
}

/**
 * Serialize one export in the sink's `format:` and journal its intent.
 *
 * One writer for both event classes, so the switch between the envelope and
 * OTLP/JSON is made once: a second copy is where the two classes would start to
 * ship different things under one `format:`.
 */
async function intendExport(
  sink: NonNullable<typeof traceSink>,
  document: runtime.TraceDocument,
  window: { readonly startedAt: string; readonly endedAt: string; readonly traceparent?: string },
): Promise<runtime.DeliveryRecord> {
  const parent = parseTraceparent(window.traceparent);
  const body =
    sink.format === "otlp"
      ? JSON.stringify(
          exportRequest(document, {
            target: deployTarget,
            artifact: ARTIFACT_HASH,
            compiler: COMPILER_VERSION,
            startedAt: window.startedAt,
            endedAt: window.endedAt,
            ...(parent === undefined ? {} : { parent }),
          }),
        )
      : JSON.stringify(document);
  return await intendDelivery({
    execution: document.execution_id,
    kind: "trace_sink",
    event: "settled",
    url: sink.url,
    body,
    // A trace export reports no pauses: it is the record of a run — or of a
    // detached delivery — that has stopped.
    pauses: [],
  });
}

/**
 * Whether one `trace_sink` row is its execution's **own** export, rather than
 * the envelope a detached delivery under it shipped (PRD resolved q64).
 *
 * Asked of `runtime.traceSinkClass`, the one reader of the difference — which
 * the status route's report asks too — and it reads it off the body: both are
 * `trace_sink` rows of `settled` events on one execution, and the journal gains
 * no column for it. A `"detached"` row is not the export, and neither is a body
 * that cannot be read: it answers `false` — "not known to be the export" — for
 * [`exportedAlready`]'s reason: the direction "I cannot tell" resolves toward is
 * the one a receiver can dedupe.
 */
export function executionExport(record: runtime.DeliveryRecord): boolean {
  if (record.kind !== "trace_sink") return false;
  return traceSinkClass(record) === "execution";
}

// ---------------------------------------------------------------------------
// The schedule
// ---------------------------------------------------------------------------

/**
 * Whether this execution's trace export is already in the journal.
 *
 * A journal this process cannot read answers `false`, and the direction matters:
 * this is the **last** moment anything comes back to the export — the lifecycle
 * row closes as [`shipTrace`]'s caller returns — so "I cannot tell" has to
 * resolve toward the recoverable half. Delivery is at-least-once and receivers
 * dedupe on the delivery id, so a trace exported twice is a collector's
 * duplicate; a trace exported never is a run nothing will ever describe.
 *
 * **Only the execution's own export counts** ([`executionExport`]). A detached
 * `flow.*` delivery under this execution ships its envelope onto the same
 * ledger, as a `trace_sink` row of its own — usually *before* its parent
 * settles, since the parent is the one still running — and a guard that read
 * any such row as "exported" would silence the parent's trace for the life of
 * the journal (PRD resolved q64).
 */
async function exportedAlready(execution: string): Promise<boolean> {
  try {
    return (await deliveriesOf(execution)).some(executionExport);
  } catch {
    return false;
  }
}

/**
 * Work one delivery's remaining schedule (resolved q35).
 *
 * The offsets are measured from the **recorded intent**, not from now, which is
 * what makes a restart pick a delivery up where it left it rather than start
 * its schedule again: a row with two attempts on it resumes at the third
 * offset, due at `intendedAt + schedule[2]`, which may already be in the past.
 *
 * Exhaustion is recorded and is **never the execution's failure**: a delivery is
 * a courtesy the status route and the trace file backstop, not a contract worth
 * an unbounded queue.
 *
 * A row whose recorded attempts already number as many as this schedule has
 * offsets is exhausted **here**, without an attempt. It is the row a restart
 * under a shorter `AGENT_COMPOSE_CALLBACK_RETRY` than the one that wrote it
 * meets, and the loop below has nothing to do with it: there is no offset left
 * to wait for and so no attempt to record. `docs/durability.md` §3.7 gives a
 * delivery two ends and staying `pending` is neither, so the row is ended rather
 * than left for the status route to keep reporting as owed at every start for
 * the rest of the journal's life.
 *
 * **One loop per delivery in one process**, which is what [`working`] says. Two
 * of them over one row would POST it twice and then disagree in the journal
 * about what the receiver did with it.
 *
 * **An attempt the journal would not take is carried, never dropped.** `attempts`
 * on the row is the one thing a later start reads to decide how much of the
 * schedule is left, so a row that under-counts them is a delivery that makes
 * more POSTs than §3.7 bounds it to — and one still `pending` when its schedule
 * is spent is a webhook the status route reports as owed for the life of the
 * journal. See [`journaling`] for what carries them and [`insisting`] for the
 * write nothing else comes back to.
 *
 * `waiting` is what tells a **server** from a **command**. `serve` waits out
 * every offset the schedule names, because it is a process that will still be
 * there in ten minutes. `agent-compose run` passes `false`: it sends what is
 * already due — the first offset is `0`, so a sink reachable at settle is
 * delivered to before the command exits — and leaves the rest on the row for a
 * start that can work it, exactly as it leaves the whole of a `callback:`. A
 * command that waited would hold a terminal open for fifteen minutes over a
 * webhook, and one that never sent would make PRD resolved q50's "the sink
 * applies wherever executions settle, `run` included" false.
 */
export async function workDelivery(
  record: runtime.DeliveryRecord,
  auth: OutboundAuth | undefined,
  waiting: boolean,
): Promise<void> {
  if (working.has(record.id)) return;
  working.add(record.id);
  try {
    const schedule = retrySchedule();
    const intended = Date.parse(record.intendedAt);
    if (record.attempts.length >= schedule.length) {
      const spent = `the schedule this process runs under names ${schedule.length} attempt${
        schedule.length === 1 ? "" : "s"
      } and ${record.attempts.length} were already made`;
      await insisting(async () => {
        try {
          await exhaustRecordedDelivery(record.execution, record.ordinal, spent);
          return true;
        } catch (error) {
          process.stderr.write(
            `\`${record.id}\`'s exhaustion could not be journaled: ${message(error)}\n`,
          );
          return false;
        }
      });
      return;
    }
    const owed: runtime.DeliveryAttempt[] = [];
    for (let index = record.attempts.length; index < schedule.length; index += 1) {
      const due = intended + (schedule[index] ?? 0) - Date.now();
      // The one thing a command does differently: an offset that has not
      // arrived is where it stops, leaving the row `pending` for a process that
      // stays. It leaves the loop rather than returning from it, so that
      // whatever it already did is written down below.
      if (due > 0 && !waiting) break;
      await pause(due);
      const outcome = await attemptDelivery(record, auth);
      owed.push({
        at: new Date().toISOString(),
        outcome: outcome.ok ? "delivered" : "failed",
        detail: outcome.detail,
      });
      if (!outcome.ok && index < schedule.length - 1) {
        // Mid-schedule the next attempt's write is what carries whatever this
        // one could not put down, and it is due at the next offset anyway — so
        // this is tried once and no more.
        await journaling(record, owed, "pending");
        continue;
      }
      // The schedule stops here, delivered or exhausted, and nothing in this
      // process comes back to the row afterwards. So this write is insisted on
      // rather than tried: it is the one that gives the row one of §3.7's two
      // ends, and the one that tells a later start how many attempts this
      // delivery really made.
      await insisting(() => journaling(record, owed, outcome.ok ? "delivered" : "exhausted"));
      return;
    }
    // Reached only by the `break` above — every other way out of that loop
    // returns from inside it. A command that stopped at an offset it will not be
    // here for still owes the journal whatever the attempts it *did* make said,
    // or the next start reads a row that under-counts them and POSTs past the
    // bound §3.7 promises.
    await journaling(record, owed, "pending");
  } finally {
    working.delete(record.id);
  }
}

/**
 * Put the attempts this delivery has made and the journal has not taken onto its
 * row, ending it where the schedule ends, and say whether the journal took them
 * all.
 *
 * Every attempt but the last is written `pending`, because that is what the row
 * was after it: `status` states where the delivery stands after its **latest**
 * attempt, and the latest is the one this call ends on. What lands is dropped
 * from `owed` and what does not is left there for the next call, which is how a
 * journal that is briefly not there costs a row nothing but the moment.
 */
async function journaling(
  record: runtime.DeliveryRecord,
  owed: runtime.DeliveryAttempt[],
  status: runtime.DeliveryStatus,
): Promise<boolean> {
  // The oldest first, and read afresh each round because the round before it
  // took one off: the condition is "there is one still owed" written as the one
  // thing that answers it.
  for (let attempt = owed[0]; attempt !== undefined; attempt = owed[0]) {
    try {
      await recordDeliveryAttempt(
        record.execution,
        record.ordinal,
        attempt,
        owed.length === 1 ? status : "pending",
      );
    } catch (error) {
      process.stderr.write(
        `\`${record.id}\`'s attempt could not be journaled: ${message(error)}\n`,
      );
      return false;
    }
    owed.shift();
  }
  return true;
}

/**
 * Make one journal write, waiting out a journal that is briefly not there.
 *
 * The writes this is for are the ones **nothing comes back to**: the end of a
 * delivery's schedule, and the intents of a settle whose lifecycle row closes
 * the moment they return (`./serve.ts`'s `closed`). A parking's intent is the
 * third and runs its own ladder (`announcing`) because it has more to do at the
 * end of one than give up — the marks it left on the execution have to come back
 * off, and a round is worth taking only while the run is still going. Every
 * other write in these two files is followed by another that would carry it.
 *
 * The `write` says whether it landed rather than raising, because each of them
 * has its own sentence for a reader and says it itself.
 */
export async function insisting(write: () => Promise<boolean>): Promise<boolean> {
  for (let index = 0; ; index += 1) {
    if (await write()) return true;
    const wait = JOURNAL_RETRY_MS[index];
    if (wait === undefined) return false;
    await pause(wait);
  }
}

/**
 * The waits between one journal write's rounds, in milliseconds.
 *
 * Short and few, and what they are for is a journal held for a moment by a
 * second process on the same project or a disk momentarily full
 * (`docs/durability.md` §2) — not a journal that is gone. Bounded like every
 * other ladder here: a delivery is a courtesy the status route backstops (§3.7),
 * so the end of this one is a sentence on stderr rather than a retry that never
 * stops.
 */
export const JOURNAL_RETRY_MS: readonly number[] = [250, 1_000, 5_000];

/**
 * The deliveries this process is working, by delivery id.
 *
 * **A row can reach [`workDelivery`] from two directions in one start.**
 * `recover` walks the open executions first and does not wait for the replays it
 * starts (`docs/durability.md` §6.1), so an execution that re-parks with a pause
 * nothing announced journals a `parked` intent and sets its schedule going while
 * that walk is still going on — and the walk over every `pending` row after it
 * then reads the row that was written a moment ago.
 *
 * Two loops over one delivery would POST it twice under one id, which a receiver
 * dedupes, and would each record their attempts against one row, which nothing
 * dedupes: the journal would hold a delivery that made more attempts than the
 * schedule §3.7 bounds, and the two would disagree about where it ended. The set
 * is this process's only — one process at a time writes a project's journal
 * (§2), and a row's own `status` is what a later start reads.
 */
const working = new Set<string>();

/**
 * Whether this process is already working a delivery.
 *
 * Asked by the start's walk over every `pending` row (`./serve.ts`'s
 * `resumeDelivery`), which is the second direction one row is reached from: the
 * guard inside [`workDelivery`] would answer the same, and asking here is what
 * lets that walk say nothing about a row it is not the one to pick up.
 */
export function beingWorked(id: string): boolean {
  return working.has(id);
}

/**
 * POST one delivery, and say what the receiver did with it.
 *
 * Every attempt sends the **same bytes** under the same delivery id: the body
 * was serialized once, at the intent, so a signature computed here is a
 * signature over what a receiver will verify and a retry is the same delivery
 * rather than a second one wearing its id.
 *
 * The headers are grammar §13.3's table, and the two halves of an outbound
 * identity may both apply — a receiver that checks a token and a receiver that
 * verifies a signature are two receivers, and one deployment may deliver to one
 * that does both. A trace sink is signed by the same table for the same reason
 * it lands on the same ledger: a collector written against a `callback:`
 * verifies one of these unchanged (grammar §14.5).
 */
async function attemptDelivery(
  record: runtime.DeliveryRecord,
  auth: OutboundAuth | undefined,
): Promise<{ readonly ok: boolean; readonly detail: string }> {
  const headers: Record<string, string> = {
    "content-type": "application/json",
    "X-AgentCompose-Event": record.event,
    "X-AgentCompose-Delivery": record.id,
    "X-AgentCompose-Ordinal": String(record.ordinal),
    // The **intent's** instant, so every attempt of one delivery agrees about
    // when the event happened. A per-attempt stamp would make two copies of one
    // delivery disagree about the thing they report.
    "X-AgentCompose-Timestamp": record.intendedAt,
  };
  if (auth?.hmac !== undefined) {
    // Fixed at HMAC-SHA256 written in hex, with no keys of its own, so one
    // receiver-side recipe verifies every agent-compose deployment (D127).
    headers["X-AgentCompose-Signature"] = `sha256=${createHmac(
      "sha256",
      secret(auth.hmac.secretEnv),
    )
      .update(record.body)
      .digest("hex")}`;
  }
  if (auth?.bearer !== undefined) {
    // Written as authored: capitalisation is the receiver's to read, never to
    // match, and the compiler has already refused a name the delivery writes
    // itself (grammar 13.3, D127).
    headers[auth.bearer.header] = `${auth.bearer.prefix}${secret(auth.bearer.tokenEnv)}`;
  }
  try {
    const answered = await fetch(record.url, {
      method: "POST",
      headers,
      body: record.body,
      // **A bounded schedule has to be bounded in wall-clock time too**
      // (resolved q35). A receiver that completes the handshake and never
      // answers is the ordinary shape of an unreachable one, and the runtime
      // this app is pinned to gives `fetch` no timeout of its own — so without
      // this an attempt never returns, the row stays `pending` for the life of
      // the process, and the delivery is neither retried nor exhausted while the
      // status route reports an execution that finished minutes ago as owing a
      // webhook. An attempt that runs out is a failed attempt like any other and
      // the schedule carries on to the next offset.
      signal: AbortSignal.timeout(DELIVERY_TIMEOUT_MS),
      // **A redirect is not followed**, which `fetch`'s default of `follow`
      // would do (grammar 13.3, Decision D127). `callback_allow:` is the whole
      // of where a signed delivery may go, and it is matched against the URL the
      // trigger produced — so following a `Location:` would carry this report,
      // its `X-AgentCompose-Signature` and a `callback_auth: bearer` under its
      // author's own header name to a host the list admits nowhere. What a
      // cross-origin redirect strips is a fixed list of standard credential
      // headers — never a name a composition chose, and never the body's
      // signature. The second half is quieter and worse: a `301`, `302` or
      // `303` rewrites the request to a bodyless `GET`, so an allowlisted
      // receiver that redirects to itself would answer `2xx` to a request
      // carrying no report and the row would be journaled `delivered`. A trace
      // sink is not allowlisted and follows the rule anyway: an operator's
      // address is where the trace goes, and a `Location:` is somebody else's
      // opinion about where it should have gone.
      redirect: "manual",
    });
    const ok = answered.status >= 200 && answered.status < 300;
    const moved = answered.status >= 300 && answered.status < 400;
    return {
      ok,
      detail: moved
        ? `the receiver answered ${answered.status} and a delivery follows no redirect: it goes where it was addressed or nowhere`
        : `the receiver answered ${answered.status}`,
    };
  } catch (error) {
    // Named rather than left as the runtime's own wording, which differs
    // between them: what a reader of the journal needs to know is that the
    // receiver was reached and said nothing, not which class the abort arrived
    // in.
    const out = (error as { name?: unknown } | null)?.name === "TimeoutError";
    return {
      ok: false,
      detail: out
        ? `the receiver did not answer within ${DELIVERY_TIMEOUT_MS / 1000}s`
        : message(error),
    };
  }
}

/**
 * How long one attempt waits for a receiver, in milliseconds
 * (`docs/durability.md` §3.7).
 *
 * Normative and not configurable: a delivery is a courtesy the status route
 * backstops, and ten seconds is what the receivers of the world are written
 * against. `AGENT_COMPOSE_CALLBACK_RETRY` shortens the *schedule* for a
 * diagnostic run; nothing shortens this, because a deployment that needed to
 * would be a deployment whose receiver is the thing to fix.
 */
const DELIVERY_TIMEOUT_MS = 10_000;

/**
 * The retry schedule a delivery is worked on, in milliseconds from its intent.
 *
 * The default is `docs/durability.md`'s normative one — five attempts across
 * fifteen minutes — and `AGENT_COMPOSE_CALLBACK_RETRY` overrides it with a
 * comma-separated list of grammar 4.4 durations, which is what a test or a
 * diagnostic run shortens it with. A value that is not one is a **usage error**
 * refused at launch rather than a setting nobody read, which is D50's posture
 * applied to an environment variable: a schedule silently ignored is a
 * deployment that believes its callbacks retry in seconds and finds out
 * otherwise ten minutes later.
 *
 * One schedule for both kinds of delivery, under the name the first of them
 * gave it: a deployment that shortened its webhooks for a diagnostic run and
 * found its trace exports still on the fifteen-minute ladder would have two
 * schedules to reason about where §3.7 documents one.
 */
export function retrySchedule(): readonly number[] {
  const written = process.env[CALLBACK_RETRY];
  if (written === undefined) return CALLBACK_SCHEDULE;
  // **Set to nothing is set**, and it is the empty list `docs/durability.md`
  // §3.7 refuses by name. Read as unset it would be the quietest form of the
  // failure D50 is about: `AGENT_COMPOSE_CALLBACK_RETRY=$SHORT_SCHEDULE` with
  // the variable unset in the wrapper starts clean on the fifteen-minute
  // schedule, and the diagnostic run somebody wrote it for waits ten minutes for
  // a retry they believed was a second away.
  if (written.trim() === "") {
    throw new CallbackRetryError(
      `\`${CALLBACK_RETRY}\` is set to an empty list, which names no attempt at all: give it at least one offset, such as \`0s\`, or unset it for the schedule \`docs/durability.md\` states`,
    );
  }
  const offsets: number[] = [];
  for (const entry of written.split(",")) {
    const matched = /^([0-9]+)(ms|s|m|h)$/.exec(entry.trim());
    const unit = matched === null ? undefined : UNITS[matched[2] ?? ""];
    if (matched === null || unit === undefined) {
      throw new CallbackRetryError(
        `\`${CALLBACK_RETRY}=${written}\` is not a comma-separated list of durations: \`${entry.trim()}\` is not one of \`<integer>ms\`, \`<integer>s\`, \`<integer>m\` or \`<integer>h\` (grammar 4.4)`,
      );
    }
    offsets.push(Number(matched[1]) * unit);
  }
  // No empty-list case below: `split(",")` answers at least one entry for every
  // string, and the one string whose entry is empty was refused above.
  return offsets;
}

/** What `AGENT_COMPOSE_CALLBACK_RETRY` was set to and could not mean. */
export class CallbackRetryError extends Error {
  constructor(detail: string) {
    super(detail);
    this.name = "CallbackRetryError";
  }
}

/** The variable that shortens the schedule, for a test or a diagnostic run. */
const CALLBACK_RETRY = "AGENT_COMPOSE_CALLBACK_RETRY";

/**
 * The normative schedule of `docs/durability.md` §3.7: five attempts at `+0s`,
 * `+15s`, `+60s`, `+240s` and `+600s` from the intent.
 */
const CALLBACK_SCHEDULE: readonly number[] = [0, 15_000, 60_000, 240_000, 600_000];

/** Grammar 4.4's units, in milliseconds. */
const UNITS: Readonly<Record<string, number>> = {
  ms: 1,
  s: 1_000,
  m: 60_000,
  h: 3_600_000,
};

// ---------------------------------------------------------------------------
// Small shared things
// ---------------------------------------------------------------------------

/** Wait out one retry offset, without holding the process open for it. */
export function pause(milliseconds: number): Promise<void> {
  if (milliseconds <= 0) return Promise.resolve();
  return new Promise<void>((resolve) => {
    const timer: unknown = setTimeout(resolve, milliseconds);
    if (typeof (timer as { unref?: () => void }).unref === "function") {
      (timer as { unref: () => void }).unref();
    }
  });
}

/**
 * The resolved value of one credential's `${ENV}` reference.
 *
 * Present by construction: `src/env.ts` lists every credential this composition
 * names — a trigger's, and the deploy layer's own — and `src/index.ts` resolves
 * the whole list at module scope, so a deployment missing one never reaches a
 * route or a delivery (grammar 4.3, PRD resolved q15). The fallback is what keeps
 * a comparison constant-time rather than a `TypeError` that would answer `500` on
 * the one request that mattered.
 *
 * What that presence check does **not** cover is a variable set to the empty
 * string, which it counts as set — so the empty string this answers is a real
 * answer rather than only the unreachable one, and it is refused at every
 * surface that would spend or compare it: `./serve.ts`'s `blankCredentials`
 * refuses the app at launch over any of the five — a trigger's `auth:` and
 * `callback_auth:`, and the deploy layer's `trace_sink.auth:` ([`blankSinkCredentials`])
 * — `verified` refuses an inbound comparison against one for the window a launch
 * check cannot cover, and `./cli.ts`'s `shipped` leaves a trace export in the
 * journal rather than signing it with nothing, which is that same launch refusal
 * for a command that has no launch.
 *
 * It lives here, in the module that **spends** a credential, and `./serve.ts`
 * verifies with the same reader: two readings of one variable that disagreed
 * about an unset one would be a route that admits a caller a delivery could not
 * have signed for.
 */
export function secret(variable: string): string {
  return process.env[variable] ?? "";
}

/** One error's text, however it arrived. */
export function message(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
